import * as THREE from 'three'
import type { SelectionAABB } from '../../stores/scene'
import {
  createOBBSegments,
  liveUpdateOBB,
  disposeOBBSegments,
  SELECTION_STYLES,
  type OBBSegmentResult,
} from './obb-line-segment-builder'

// re-export 供外部调用方（useSelection.ts 等）使用，保持 import 路径向后兼容
export type { HighlightLabel, HighlightStyle } from './obb-line-segment-builder'

export interface BoundsHighlightRendererOptions {
  scene: THREE.Scene
  camera: THREE.Camera
}

export class BoundsHighlightRenderer {
  private scene: THREE.Scene
  /** 缓存当前 OBB 资源，live 更新时直接操作，不重建 */
  private obb: OBBSegmentResult | null = null
  private currentLabel: import('./obb-line-segment-builder').HighlightLabel = 'unlabeled'
  private currentAABB: SelectionAABB | null = null

  constructor(options: BoundsHighlightRendererOptions) {
    this.scene = options.scene
    void options.camera
  }

  /**
   * 显示或更新 AABB 高亮框。
   *
   * 【两阶段策略（v1.3.0）+ colors 增量（v1.5.0）】
   * - label 变更（或首次）→ rebuildGroup()（完整重建，需要新建材质）
   * - 同 label 的 AABB 数据更新（live 拖拽路径）→ liveUpdateGroup()（零销毁/零重建）
   */
  show(aabb: SelectionAABB, label: import('./obb-line-segment-builder').HighlightLabel): void {
    const labelChanged = label !== this.currentLabel
    this.currentAABB = aabb
    this.currentLabel = label

    if (labelChanged || !this.obb) {
      this.rebuildGroup()
    } else {
      this.liveUpdateGroup(aabb)
    }
  }

  /** 隐藏高亮框 */
  hide(): void {
    this.clearGroup()
  }

  /** 更新标签（改变颜色/虚线样式） */
  setLabel(label: import('./obb-line-segment-builder').HighlightLabel): void {
    if (label === this.currentLabel || !this.currentAABB) return
    this.currentLabel = label
    this.rebuildGroup()
  }

  /** 销毁所有资源 */
  dispose(): void {
    this.clearGroup()
  }

  private clearGroup(): void {
    if (this.obb) {
      disposeOBBSegments(this.obb, this.scene)
      this.obb = null
    }
  }

  private rebuildGroup(): void {
    this.clearGroup()
    if (!this.currentAABB) return

    const style = SELECTION_STYLES[this.currentLabel]
    // v5.0.0：正面永远是本地 +Z 面（face 0），rotationY 已包含正面方向信息
    this.obb = createOBBSegments(this.currentAABB, style, 0, /* renderOrder */ 1002)
    this.scene.add(this.obb.group)
  }

  /**
   * 【v1.3.0】Live 增量更新：仅更新 geometry 顶点数据和 group 变换，零 WebGL 对象重建。
   *
   * 触发条件：label 不变，仅 AABB 数据变化（translate / scale 拖拽的 live 路径）。
   */
  private liveUpdateGroup(aabb: SelectionAABB): void {
    if (!this.obb) return
    const style = SELECTION_STYLES[this.currentLabel]
    liveUpdateOBB(this.obb, aabb, style, 0)
  }
}
