<script setup lang="ts">
import { ref } from 'vue'
import { IconExpand, IconCollapse } from '../../utils/icons'

defineProps<{
  title: string
}>()

const isOpen = ref(true)
</script>

<template>
  <div class="mb-3">
    <button
      class="flex items-center gap-1.5 w-full h-7 text-xs font-semibold text-text-secondary
             hover:text-accent transition-colors cursor-pointer rounded-md px-1
             hover:bg-bg-hover active:bg-bg-active"
      @click="isOpen = !isOpen"
    >
      <component :is="isOpen ? IconCollapse : IconExpand" :size="12" class="text-text-subtle" />
      {{ title }}
    </button>
    <div v-show="isOpen" class="pl-4 space-y-2 mt-1">
      <slot />
    </div>
  </div>
</template>
