<!--
  OnboardingOverlay — 新手引导蒙层容器（分阶段按需触发）

  职责：
    1. 全屏半透明蒙层 + SVG mask 挖洞高亮目标
    2. 计算气泡位置并渲染 StepTooltip
    3. 监听 interactive 步骤的 awaitEvent
    4. 监听各阶段的 triggerEvent，按需激活对应阶段
    5. 窗口 resize 时重计算位置

  @changelog
  | 版本   | 变更说明                                                                    | 关联                                             |
  | v1.0.0 | 初始实现：蒙层 + SVG 挖洞 + 气泡定位 + 交互事件桥接 + resize 响应          | REQ: 新手引导系统 TECH: onboarding 架构           |
  | v2.0.0 | 重构为分阶段按需触发：监听各 phase triggerEvent；WelcomeDialog 改为 Phase A 未完成时条件显示 | REQ: 新手引导系统（分阶段触发） |
  | v2.1.0 | 首次跳过告别提示：skip 时高亮帮助菜单并显示"知道了"气泡（复用 StepTooltip hideNavigation 模式） | REQ: 引导流程收尾优化 |
  /@changelog

  @author v_djlzhou
-->
<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount, nextTick } from 'vue'
import StepTooltip from './StepTooltip.vue'
import WelcomeDialog from './WelcomeDialog.vue'
import { useOnboardingStore } from '../../stores/onboarding'
import { ONBOARDING_PHASES } from '../../constants/onboarding-steps'
import type { TooltipPlacement } from '../../constants/onboarding-steps'

const store = useOnboardingStore()

/** 欢迎弹窗可见性（仅首次进入 Phase A 前显示） */
const showWelcome = ref(false)

/** 目标元素矩形（视口坐标） */
const targetRect = ref<DOMRect | null>(null)

/** 气泡位置 */
const tooltipPos = ref({ top: 0, left: 0 })

/** 箭头相对气泡左/上边缘的偏移量（px），用于精确指向目标中心 */
const arrowOffset = ref<number | null>(null)

// ==================== 事件处理 ====================

let currentAwaitEvent: string | null = null

function handleAwaitEvent() {
  store.resolveInteraction()
}

function cleanupAwaitListener() {
  if (currentAwaitEvent) {
    document.removeEventListener(currentAwaitEvent, handleAwaitEvent)
    currentAwaitEvent = null
  }
}

function setupAwaitListener(eventName: string) {
  cleanupAwaitListener()
  currentAwaitEvent = eventName
  document.addEventListener(eventName, handleAwaitEvent)
}

// ==================== Phase 触发事件监听 ====================

/** 各阶段触发事件的 handler map（用于 unmount 时清理） */
const phaseHandlers: Array<{ event: string; handler: () => void }> = []

function setupPhaseTriggerListeners() {
  for (const phase of ONBOARDING_PHASES) {
    const handler = () => store.triggerPhase(phase.id)
    document.addEventListener(phase.triggerEvent, handler)
    phaseHandlers.push({ event: phase.triggerEvent, handler })
  }
}

function cleanupPhaseTriggerListeners() {
  for (const { event, handler } of phaseHandlers) {
    document.removeEventListener(event, handler)
  }
  phaseHandlers.length = 0
}

// ==================== 位置计算 ====================

const TOOLTIP_WIDTH = 320
const TOOLTIP_GAP = 12

function calcTooltipPosition(rect: DOMRect, placement: TooltipPlacement): { top: number; left: number } {
  const ESTIMATED_TOOLTIP_HEIGHT = 160
  switch (placement) {
    case 'bottom':
      return {
        top: rect.bottom + TOOLTIP_GAP,
        left: Math.max(8, Math.min(rect.left, window.innerWidth - TOOLTIP_WIDTH - 8)),
      }
    case 'top':
      return {
        top: rect.top - TOOLTIP_GAP - ESTIMATED_TOOLTIP_HEIGHT,
        left: Math.max(8, rect.left + rect.width / 2 - TOOLTIP_WIDTH / 2),
      }
    case 'right':
      return {
        top: Math.max(8, rect.top),
        left: rect.right + TOOLTIP_GAP,
      }
    case 'left':
      return {
        top: Math.max(8, rect.top),
        left: rect.left - TOOLTIP_WIDTH - TOOLTIP_GAP,
      }
    case 'center':
      return {
        top: rect.top + rect.height / 2 - 100,
        left: rect.left + rect.width / 2 - TOOLTIP_WIDTH / 2,
      }
    default:
      return { top: rect.bottom + TOOLTIP_GAP, left: rect.left }
  }
}

function recalcPosition() {
  const step = store.currentStep
  if (!step) {
    return
  }

  const el = document.querySelector(step.target)
  if (!el) {
    console.warn(`[Onboarding] 目标元素未找到: ${step.target}，步骤 "${step.id}" 将居中显示`)
    targetRect.value = null
    arrowOffset.value = null
    tooltipPos.value = {
      top: window.innerHeight / 2 - 100,
      left: window.innerWidth / 2 - 160,
    }
    return
  }

  const rect = el.getBoundingClientRect()
  targetRect.value = rect
  tooltipPos.value = calcTooltipPosition(rect, step.placement)

  // 计算箭头偏移：目标中心相对于气泡边缘的距离
  const placement = step.placement
  if (placement === 'top' || placement === 'bottom') {
    // 水平偏移：目标中心 X - 气泡左边缘
    arrowOffset.value = rect.left + rect.width / 2 - tooltipPos.value.left
  } else if (placement === 'left' || placement === 'right') {
    // 垂直偏移：目标中心 Y - 气泡上边缘
    arrowOffset.value = rect.top + rect.height / 2 - tooltipPos.value.top
  } else {
    arrowOffset.value = null
  }
}

// ==================== 高亮矩形 ====================

const highlightStyle = computed(() => {
  if (!targetRect.value) return null
  const padding = 4
  return {
    x: targetRect.value.left - padding,
    y: targetRect.value.top - padding,
    width: targetRect.value.width + padding * 2,
    height: targetRect.value.height + padding * 2,
    rx: 6,
    ry: 6,
  }
})

// ==================== Watch ====================

watch(
  () => store.currentStep,
  async (step) => {
    cleanupAwaitListener()
    if (!step) {
      targetRect.value = null
      return
    }
    await nextTick()
    setTimeout(() => {
      recalcPosition()
      if (step.interactive && step.awaitEvent) {
        setupAwaitListener(step.awaitEvent)
      }
    }, 100)
  },
  { immediate: true },
)

watch(
  () => store.isActive,
  () => {
    // 引导结束时清理 targetRect
    if (!store.isActive) {
      targetRect.value = null
    }
  },
)

// ==================== 生命周期 ====================

onMounted(() => {
  setupPhaseTriggerListeners()
  window.addEventListener('resize', recalcPosition)
  document.addEventListener('scroll', recalcPosition, true)

  // 首次进入：如果 Phase A 未完成，显示欢迎弹窗
  if (!store.isPhaseCompleted('open-scene')) {
    showWelcome.value = true
  }
})

onBeforeUnmount(() => {
  cleanupPhaseTriggerListeners()
  window.removeEventListener('resize', recalcPosition)
  document.removeEventListener('scroll', recalcPosition, true)
  cleanupAwaitListener()
})

// ==================== 用户操作 ====================

function onWelcomeStart() {
  showWelcome.value = false
  store.triggerPhase('open-scene')
}

function onWelcomeSkip() {
  showWelcome.value = false
  // 跳过欢迎 = 直接标记 Phase A 完成（不再提示）
  store.markPhaseCompleted('open-scene')
}

function onNext() {
  store.next()
}

function onPrev() {
  store.prev()
}

function onSkip() {
  store.skip()
}

// ==================== 跳过告别提示 ====================

/** 告别提示的气泡位置 */
const skipHintPos = ref({ top: 0, left: 0 })
const skipHintArrowOffset = ref<number | null>(null)
const skipHintTargetRect = ref<DOMRect | null>(null)

function recalcSkipHintPosition() {
  const el = document.querySelector('[data-tour="menu-help"]')
  if (!el) {
    skipHintTargetRect.value = null
    skipHintPos.value = { top: window.innerHeight / 2 - 100, left: window.innerWidth / 2 - 160 }
    skipHintArrowOffset.value = null
    return
  }
  const rect = el.getBoundingClientRect()
  skipHintTargetRect.value = rect
  skipHintPos.value = calcTooltipPosition(rect, 'bottom')
  skipHintArrowOffset.value = rect.left + rect.width / 2 - skipHintPos.value.left
}

watch(
  () => store.showSkipHint,
  async (show) => {
    if (show) {
      await nextTick()
      setTimeout(recalcSkipHintPosition, 100)
    } else {
      skipHintTargetRect.value = null
    }
  },
)

function onDismissSkipHint() {
  store.dismissSkipHint()
}

const skipHintHighlightStyle = computed(() => {
  if (!skipHintTargetRect.value) return null
  const padding = 4
  return {
    x: skipHintTargetRect.value.left - padding,
    y: skipHintTargetRect.value.top - padding,
    width: skipHintTargetRect.value.width + padding * 2,
    height: skipHintTargetRect.value.height + padding * 2,
    rx: 6,
    ry: 6,
  }
})
</script>

<template>
  <!-- 欢迎弹窗（仅首次进入 Phase A 前） -->
  <WelcomeDialog
    :visible="showWelcome"
    @start="onWelcomeStart"
    @skip="onWelcomeSkip"
  />

  <!-- Tour 蒙层 + 高亮 + 气泡 -->
  <Teleport to="body">
    <Transition name="overlay-fade">
      <div v-if="store.isActive && store.currentStep && !store.showSkipHint" class="onboarding-overlay">
        <svg
          class="onboarding-overlay__mask"
          :class="{ 'onboarding-overlay__mask--passthrough': store.isWaitingForInteraction }"
          width="100%" height="100%"
        >
          <defs>
            <mask id="onboarding-spotlight">
              <rect x="0" y="0" width="100%" height="100%" fill="white" />
              <rect
                v-if="highlightStyle"
                :x="highlightStyle.x"
                :y="highlightStyle.y"
                :width="highlightStyle.width"
                :height="highlightStyle.height"
                :rx="highlightStyle.rx"
                :ry="highlightStyle.ry"
                fill="black"
              />
            </mask>
          </defs>
          <rect
            x="0" y="0"
            width="100%" height="100%"
            fill="rgba(0, 0, 0, 0.55)"
            mask="url(#onboarding-spotlight)"
          />
        </svg>

        <!-- 高亮边框 -->
        <div
          v-if="highlightStyle"
          class="onboarding-overlay__highlight"
          :style="{
            top: `${highlightStyle.y}px`,
            left: `${highlightStyle.x}px`,
            width: `${highlightStyle.width}px`,
            height: `${highlightStyle.height}px`,
            borderRadius: `${highlightStyle.rx}px`,
          }"
        />

        <!-- 步骤气泡 -->
        <StepTooltip
          :title="store.currentStep.title"
          :content="store.currentStep.content"
          :placement="store.currentStep.placement"
          :current-step="store.currentStepIndex"
          :total-steps="store.totalSteps"
          :is-last-step="store.isLastStep"
          :is-waiting="store.isWaitingForInteraction"
          :position="tooltipPos"
          :arrow-offset="arrowOffset"
          @next="onNext"
          @prev="onPrev"
          @skip="onSkip"
        />
      </div>
    </Transition>

    <!-- 跳过告别提示：首次跳过时高亮帮助菜单 -->
    <Transition name="overlay-fade">
      <div v-if="store.showSkipHint" class="onboarding-overlay">
        <svg class="onboarding-overlay__mask" width="100%" height="100%">
          <defs>
            <mask id="onboarding-skip-hint-spotlight">
              <rect x="0" y="0" width="100%" height="100%" fill="white" />
              <rect
                v-if="skipHintHighlightStyle"
                :x="skipHintHighlightStyle.x"
                :y="skipHintHighlightStyle.y"
                :width="skipHintHighlightStyle.width"
                :height="skipHintHighlightStyle.height"
                :rx="skipHintHighlightStyle.rx"
                :ry="skipHintHighlightStyle.ry"
                fill="black"
              />
            </mask>
          </defs>
          <rect
            x="0" y="0"
            width="100%" height="100%"
            fill="rgba(0, 0, 0, 0.55)"
            mask="url(#onboarding-skip-hint-spotlight)"
          />
        </svg>

        <!-- 高亮边框 -->
        <div
          v-if="skipHintHighlightStyle"
          class="onboarding-overlay__highlight"
          :style="{
            top: `${skipHintHighlightStyle.y}px`,
            left: `${skipHintHighlightStyle.x}px`,
            width: `${skipHintHighlightStyle.width}px`,
            height: `${skipHintHighlightStyle.height}px`,
            borderRadius: `${skipHintHighlightStyle.rx}px`,
          }"
        />

        <!-- 告别气泡（复用 StepTooltip，简化为仅"知道了"按钮） -->
        <StepTooltip
          title="随时重新引导"
          content="已跳过当前引导。如果以后想重新了解操作流程，可以在「帮助 → 重新引导」中随时找到。"
          placement="bottom"
          :current-step="0"
          :total-steps="1"
          :is-last-step="true"
          :is-waiting="false"
          :position="skipHintPos"
          :arrow-offset="skipHintArrowOffset"
          :hide-navigation="true"
          confirm-label="知道了"
          @next="onDismissSkipHint"
        />
      </div>
    </Transition>
  </Teleport>
</template>

<style scoped>
.onboarding-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  pointer-events: none;
}

.onboarding-overlay__mask {
  position: absolute;
  inset: 0;
  pointer-events: auto;
}

.onboarding-overlay__mask--passthrough {
  pointer-events: none;
}

.onboarding-overlay__highlight {
  position: fixed;
  border: 2px solid var(--color-accent);
  box-shadow: 0 0 0 4px var(--color-accent-muted);
  pointer-events: none;
  transition: all 0.25s ease;
  z-index: 10001;
}

.overlay-fade-enter-active,
.overlay-fade-leave-active {
  transition: opacity 0.2s ease;
}
.overlay-fade-enter-from,
.overlay-fade-leave-to {
  opacity: 0;
}
</style>
