<!--
  StepTooltip — 引导步骤气泡组件

  @changelog
  | 版本   | 变更说明                                                         | 关联                                    |
  | v1.0.0 | 初始实现：支持 5 方向定位 + 步数指示 + 上下步按钮 + 跳过         | REQ: 新手引导系统 TECH: onboarding 架构  |
  | v1.1.0 | 新增 hideNavigation/confirmLabel props，支持简化模式（仅确认按钮） | REQ: 引导流程收尾优化                   |
  /@changelog

  @author v_djlzhou
-->
<script setup lang="ts">
import { computed } from 'vue'
import type { TooltipPlacement } from '../../constants/onboarding-steps'

const props = defineProps<{
  title: string
  content: string
  placement: TooltipPlacement
  currentStep: number
  totalSteps: number
  isLastStep: boolean
  isWaiting: boolean
  /** 气泡定位坐标（相对视口） */
  position: { top: number; left: number }
  /** 箭头偏移量（px），目标中心相对于气泡边缘的距离，null 时居中 */
  arrowOffset?: number | null
  /** 隐藏步数/导航/跳过，仅显示确认按钮（用于告别提示等场景） */
  hideNavigation?: boolean
  /** 确认按钮文案（hideNavigation=true 时生效，默认"知道了"） */
  confirmLabel?: string
}>()

const emit = defineEmits<{
  (e: 'next'): void
  (e: 'prev'): void
  (e: 'skip'): void
}>()

const positionStyle = computed(() => ({
  top: `${props.position.top}px`,
  left: `${props.position.left}px`,
}))

/** 箭头动态内联样式 */
const arrowStyle = computed(() => {
  if (props.arrowOffset == null) return undefined
  const placement = props.placement
  const ARROW_HALF = 5 // 箭头宽高 10px 的一半
  if (placement === 'top' || placement === 'bottom') {
    // 水平偏移，减去箭头一半使其中心对准目标
    const clamped = Math.max(12, Math.min(props.arrowOffset - ARROW_HALF, 320 - 12))
    return { left: `${clamped}px` }
  } else if (placement === 'left' || placement === 'right') {
    // 垂直偏移
    const clamped = Math.max(12, Math.min(props.arrowOffset - ARROW_HALF, 300))
    return { top: `${clamped}px` }
  }
  return undefined
})
</script>

<template>
  <div
    class="step-tooltip"
    :class="`step-tooltip--${placement}`"
    :style="positionStyle"
  >
    <!-- 箭头 -->
    <div class="step-tooltip__arrow" :class="`step-tooltip__arrow--${placement}`" :style="arrowStyle" />

    <!-- 内容区 -->
    <div class="step-tooltip__body">
      <div class="step-tooltip__header">
        <span class="step-tooltip__title">{{ title }}</span>
        <span v-if="!hideNavigation" class="step-tooltip__counter">{{ currentStep + 1 }} / {{ totalSteps }}</span>
      </div>
      <p class="step-tooltip__content">{{ content }}</p>

      <!-- 交互等待提示 -->
      <p v-if="isWaiting && !hideNavigation" class="step-tooltip__waiting">
        <span class="step-tooltip__waiting-dot" />
        请完成此步骤操作后继续…
      </p>

      <!-- 简化模式：仅确认按钮 -->
      <div v-if="hideNavigation" class="step-tooltip__actions" style="justify-content: flex-end;">
        <button
          class="step-tooltip__btn step-tooltip__btn--primary"
          @click="emit('next')"
        >
          {{ confirmLabel || '知道了' }}
        </button>
      </div>

      <!-- 完整导航模式 -->
      <div v-else class="step-tooltip__actions">
        <button class="step-tooltip__btn step-tooltip__btn--skip" @click="emit('skip')">
          跳过引导
        </button>
        <div class="step-tooltip__nav">
          <button
            v-if="currentStep > 0"
            class="step-tooltip__btn step-tooltip__btn--secondary"
            @click="emit('prev')"
          >
            上一步
          </button>
          <button
            class="step-tooltip__btn step-tooltip__btn--primary"
            :disabled="isWaiting"
            @click="emit('next')"
          >
            {{ isLastStep ? '完成' : '下一步' }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

