import { defineStore } from 'pinia'
import { ref } from 'vue'
import type { AxisLock, CameraMode, ToolType, TransformSpace } from '../types/editor'

/**
 * transformSpace 持久化键。
 *
 * 命名对齐 scene.ts 的 `splat-studio.recent-urls` 风格（dot-case + 模块前缀）；
 * 决策见 ADR-005（05_design_tech.md §Decisions）。
 */
const TRANSFORM_SPACE_STORAGE_KEY = 'splat-studio.transform-space'

/**
 * Safe 模式读取 transformSpace：
 * - 非法值 / 读失败 / 隐身模式 / 配额异常 → 降级为 'world'（默认坐标系）
 * - 参考模式：`scene.ts` 的 `loadRecentUrlsSafe`
 */
function loadTransformSpaceSafe(): TransformSpace {
  try {
    const v = localStorage.getItem(TRANSFORM_SPACE_STORAGE_KEY)
    return v === 'local' ? 'local' : 'world'
  } catch {
    // Safari 隐身 / 配额满 / 被禁用
    return 'world'
  }
}

/**
 * Safe 模式写入 transformSpace：
 * - 失败时静默降级（不抛异常，不污染 console；UI 状态仍在内存里，刷新后回退默认）
 * - RISK-DA006 已接受此降级策略
 */
function saveTransformSpaceSafe(v: TransformSpace): void {
  try {
    localStorage.setItem(TRANSFORM_SPACE_STORAGE_KEY, v)
  } catch {
    // quota / privacy mode — 静默
  }
}

export const useEditorStore = defineStore('editor', () => {
  // 默认工具为 'select'：启动时不激活任何变换 Gizmo，仅显示选中线框高亮。
  // 用户需显式按 G/R/T 或点击工具栏按钮才进入变换模式。
  // 三模式按钮在工具栏中常驻可见，但默认无高亮激活态。
  const activeTool = ref<ToolType>('select')
  const cameraMode = ref<CameraMode>('Perspective')

  // 记录进入 region-select / face-pick 前的工具，ESC 退出后恢复
  const _toolBeforeTransient = ref<ToolType>('select')

  // 轴锁与坐标系（v1.0.0）：
  //  · axisLock 仅运行时；切换工具时自动清除（ADR-004）
  //  · transformSpace 从 localStorage 恢复，切换时持久化
  const axisLock = ref<AxisLock>(null)
  const transformSpace = ref<TransformSpace>(loadTransformSpaceSafe())

  /**
   * 已标实体常驻线框开关（v1.2.0）。
   *
   * 默认 false（进编辑器不显示），用户通过 ViewportToolbar 眼睛按钮手动开启。
   * 不持久化到 localStorage —— 每次进编辑器都默认隐藏，按需开启。
   */
  const persistentHighlightEnabled = ref<boolean>(false)

  /**
   * 切换当前编辑器工具。
   *
   * 【v1.0.0 副作用】切到不同 tool 时清除轴锁 —— 满足 PRD §2.2 验收：
   *   "G X → 切 R → 轴锁必须消失，不能带着 X 锁进 rotate 模式"
   *
   * 若 tool === activeTool.value（重复点击），不动 axisLock（允许 G X 后再点工具栏 G 不丢锁）。
   *
   * 【v2.0.0】进入 region-select / face-pick 前快照当前工具到 _toolBeforeTransient，
   *   供 restoreToolBeforeTransient() 恢复。
   */
  function setTool(tool: ToolType) {
    if (tool !== activeTool.value) {
      // 进入瞬态工具前记住"上一个稳态"
      // 仅当从稳态（非 region-select/face-pick）进入时才快照，
      // 瞬态之间互切（如 face-pick → region-select）不覆盖，保留最初的稳态
      const isTransient = (t: ToolType) => t === 'region-select' || t === 'face-pick'
      if (isTransient(tool) && !isTransient(activeTool.value)) {
        _toolBeforeTransient.value = activeTool.value
      }
      axisLock.value = null
    }
    activeTool.value = tool
  }

  function setCameraMode(mode: CameraMode) {
    cameraMode.value = mode
  }

  /**
   * 切换/设置轴锁。
   *
   * 语义（ADR 外，来自 PRD §2.2）：
   *   · 当前已锁相同轴 → 解锁（置 null）
   *   · 当前锁不同轴 / 当前未锁 → 切到目标轴
   *
   * 【v1.1.0 业务守卫】rotate 模式下仅接受 Y 轴：
   *   prop 业务约束只允许绕 Y 旋转（sanitizeProxyTransform 钉死 rotation.x/z=0），
   *   锁 X/Z 会让 Gizmo 所有手柄消失（lockAllowY=false），形成"按了没反应"的死按钮
   *   反模式（EV-014）。故在 store 层面静默拒绝 —— 作为"单一事实源"兜底，
   *   防御所有调用方（快捷键 / 未来 Toolbar 按钮 / 外部脚本）。
   *
   *   未来放开 prop 三轴旋转时（sanitizeProxyTransform 解除钉死），仅需删除此守卫。
   *
   * 典型快捷键流：G → X（锁 X）→ X（解锁）；G → X（锁 X）→ Y（切到 Y 锁）。
   */
  function toggleAxisLock(axis: 'X' | 'Y' | 'Z') {
    if (activeTool.value === 'rotate' && axis !== 'Y') return
    axisLock.value = axisLock.value === axis ? null : axis
  }

  /**
   * 直接清除轴锁（置 null）。
   *
   * 调用方：
   *   · Escape 快捷键（useTransformShortcuts — B06）
   *   · setTool 内部（工具切换副作用）
   *   · 未来可能的外部重置入口
   */
  function clearAxisLock() {
    axisLock.value = null
  }

  /**
   * 切换坐标系 world ↔ local，并同步到 localStorage。
   *
   * 快捷键：Backquote（`` ` ``）— 由 useTransformShortcuts 路由（B06）。
   * 失败降级：localStorage 写入失败时仅失去"刷新后保留"能力，不影响当前会话。
   *
   * 【v1.1.0 业务守卫】rotate / scale 模式下静默拒绝：
   *   · rotate：业务约束 rotation.x=z=0，local Y 轴数学上恒等于 world Y 轴，切换视觉无效
   *   · scale：three r169 TransformControls 源码层对 scale 强制 local（忽略 space 参数）
   *   两者都属于 EV-014 死按钮反模式 —— 允许切换会让 StatusBar/Toolbar 徽标文字变化，
   *   但 Gizmo 行为纹丝不动，误导用户。故在 store 层统一拒绝。
   *
   *   未来 three.js 修复 scale space 支持 或 业务放开 rotation.x/z 时，删除对应判断即可。
   */
  function toggleTransformSpace() {
    if (activeTool.value === 'rotate' || activeTool.value === 'scale') return
    transformSpace.value = transformSpace.value === 'world' ? 'local' : 'world'
    saveTransformSpaceSafe(transformSpace.value)
  }

  /**
   * 恢复进入 region-select / face-pick 前的工具状态。
   *
   * 典型调用方：ESC 退出框选 / 取消 facePicking。
   * 语义：如果进入框选前是 'select'（无 Gizmo），退出后仍回到 'select'；
   *        如果进入前是 'move'，退出后回到 'move'（显示 Gizmo）。
   */
  function restoreToolBeforeTransient() {
    activeTool.value = _toolBeforeTransient.value
    axisLock.value = null
  }

  /** 切换已标实体常驻线框显示/隐藏（v1.2.0） */
  function togglePersistentHighlight(): void {
    persistentHighlightEnabled.value = !persistentHighlightEnabled.value
  }

  return {
    activeTool,
    cameraMode,
    axisLock,
    transformSpace,
    persistentHighlightEnabled,
    setTool,
    setCameraMode,
    toggleAxisLock,
    clearAxisLock,
    toggleTransformSpace,
    restoreToolBeforeTransient,
    togglePersistentHighlight,
  }
})
