/**
 * SelectionOverlay — 2D 拖拽矩形 DOM 叠加层
 *
 * 在 Viewport 容器内叠加一个半透明 DOM 元素，显示用户拖拽的 2D 矩形区域。
 * 使用 `pointer-events: none` 确保不拦截 ViewerSDK canvas 的 pointer 事件。
 *
 * <!-- @changelog -->
 * <table>
 *   <tr><th>版本</th><th>变更说明</th><th>关联</th></tr>
 *   <tr>
 *     <td>v1.0.0</td>
 *     <td>从 viewer-sdk 迁移 SelectionOverlay 到 H5 本地 useSelection 模块</td>
 *     <td>REQ: 20260427-框选迁移H5<br/>TECH: 04_design_tech-design.md §3.4.3</td>
 *   </tr>
 * </table>
 * <!-- /@changelog -->
 *
 * @author v_djlzhou
 */
export class SelectionOverlay {
  private container: HTMLElement
  private overlayEl: HTMLDivElement | null = null

  constructor(container: HTMLElement) {
    this.container = container
    this.createOverlayElement()
  }

  /** 显示拖拽矩形 */
  show(startX: number, startY: number, endX: number, endY: number): void {
    if (!this.overlayEl) return

    const rect = this.container.getBoundingClientRect()
    const left = Math.min(startX, endX) - rect.left
    const top = Math.min(startY, endY) - rect.top
    const width = Math.abs(endX - startX)
    const height = Math.abs(endY - startY)

    Object.assign(this.overlayEl.style, {
      left: `${left}px`,
      top: `${top}px`,
      width: `${width}px`,
      height: `${height}px`,
      display: 'block',
    })
  }

  /** 隐藏拖拽矩形 */
  hide(): void {
    if (this.overlayEl) {
      this.overlayEl.style.display = 'none'
    }
  }

  /** 销毁 DOM 元素 */
  dispose(): void {
    if (this.overlayEl) {
      this.overlayEl.remove()
      this.overlayEl = null
    }
  }

  private createOverlayElement(): void {
    const el = document.createElement('div')
    Object.assign(el.style, {
      position: 'absolute',
      pointerEvents: 'none',
      zIndex: '10',
      border: '2px dashed rgba(255, 204, 0, 0.8)',
      background: 'rgba(255, 204, 0, 0.08)',
      display: 'none',
    })
    this.container.appendChild(el)
    this.overlayEl = el
  }
}
