import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { ONBOARDING_PHASES } from '../constants/onboarding-steps'
import type { OnboardingStep, OnboardingPhase } from '../constants/onboarding-steps'

const STORAGE_KEY = 'splat-studio.onboarding-phases'
const SKIP_HINT_KEY = 'splat-studio.onboarding-skip-hinted'

/**
 * Safe 模式读取已完成阶段集合。
 * 存储格式：JSON 数组 ["open-scene", "basic-ui", ...]
 */
function loadCompletedPhasesSafe(): Set<string> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return new Set()
    const arr = JSON.parse(raw)
    return new Set(Array.isArray(arr) ? arr : [])
  } catch {
    return new Set()
  }
}

function saveCompletedPhasesSafe(phases: Set<string>): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify([...phases]))
  } catch {
    // 静默降级
  }
}

export const useOnboardingStore = defineStore('onboarding', () => {
  // ==================== 状态 ====================

  /** 已完成的阶段 ID 集合 */
  const completedPhases = ref<Set<string>>(loadCompletedPhasesSafe())

  /** 当前激活的阶段 ID（null = 无激活阶段） */
  const activePhaseId = ref<string | null>(null)

  /** 当前阶段内的步骤索引 */
  const currentStepIndex = ref(-1)

  /** 是否正在等待用户交互完成 */
  const isWaitingForInteraction = ref(false)

  /** 是否正在显示"跳过告别"提示（首次跳过时指向帮助菜单） */
  const showSkipHint = ref(false)

  // ==================== Getters ====================

  /** 引导是否激活中 */
  const isActive = computed(() => activePhaseId.value !== null)

  /** 当前激活的阶段配置 */
  const activePhase = computed<OnboardingPhase | null>(() => {
    if (!activePhaseId.value) return null
    return ONBOARDING_PHASES.find((p) => p.id === activePhaseId.value) ?? null
  })

  /** 当前步骤配置 */
  const currentStep = computed<OnboardingStep | null>(() => {
    const phase = activePhase.value
    if (!phase || currentStepIndex.value < 0 || currentStepIndex.value >= phase.steps.length) {
      return null
    }
    return phase.steps[currentStepIndex.value]
  })

  /** 当前阶段总步数 */
  const totalSteps = computed(() => activePhase.value?.steps.length ?? 0)

  /** 是否为当前阶段最后一步 */
  const isLastStep = computed(() => {
    const phase = activePhase.value
    if (!phase) return false
    return currentStepIndex.value === phase.steps.length - 1
  })

  /** 是否所有阶段都已完成 */
  const allPhasesCompleted = computed(() =>
    ONBOARDING_PHASES.every((p) => completedPhases.value.has(p.id)),
  )

  /** 判断某阶段是否已完成 */
  function isPhaseCompleted(phaseId: string): boolean {
    return completedPhases.value.has(phaseId)
  }

  // ==================== Actions ====================

  /**
   * 触发指定阶段。
   * 如果该阶段已完成或当前有活跃阶段，则忽略。
   */
  function triggerPhase(phaseId: string) {
    // 已完成的不再触发
    if (completedPhases.value.has(phaseId)) return
    // 当前有活跃阶段时不打断
    if (activePhaseId.value !== null) return

    const phase = ONBOARDING_PHASES.find((p) => p.id === phaseId)
    if (!phase || phase.steps.length === 0) return

    activePhaseId.value = phaseId
    currentStepIndex.value = 0
    isWaitingForInteraction.value = phase.steps[0].interactive ?? false
  }

  /** 进入下一步 */
  function next() {
    if (!isActive.value) return
    if (isWaitingForInteraction.value) return

    if (isLastStep.value) {
      completePhase()
      return
    }

    currentStepIndex.value++
    const phase = activePhase.value!
    const step = phase.steps[currentStepIndex.value]
    isWaitingForInteraction.value = step.interactive ?? false
  }

  /** 返回上一步 */
  function prev() {
    if (!isActive.value || currentStepIndex.value <= 0) return
    currentStepIndex.value--
    isWaitingForInteraction.value = false
  }

  /** 跳过当前阶段 */
  function skip() {
    // 首次跳过时，显示告别提示指向帮助菜单
    const hasHinted = localStorage.getItem(SKIP_HINT_KEY)
    if (!hasHinted) {
      localStorage.setItem(SKIP_HINT_KEY, '1')
      showSkipHint.value = true
      return
    }
    completePhase()
  }

  /** 关闭跳过告别提示，真正完成阶段 */
  function dismissSkipHint() {
    showSkipHint.value = false
    completePhase()
  }

  /** 完成当前阶段 */
  function completePhase() {
    if (activePhaseId.value) {
      completedPhases.value.add(activePhaseId.value)
      saveCompletedPhasesSafe(completedPhases.value)
    }
    activePhaseId.value = null
    currentStepIndex.value = -1
    isWaitingForInteraction.value = false
  }

  /** 解除交互等待 */
  function resolveInteraction() {
    if (!isWaitingForInteraction.value) return
    isWaitingForInteraction.value = false
    next()
  }

  /** 直接标记某阶段为已完成（不激活阶段流程） */
  function markPhaseCompleted(phaseId: string) {
    completedPhases.value.add(phaseId)
    saveCompletedPhasesSafe(completedPhases.value)
  }

  /**
   * 重置引导，根据当前应用状态智能选择起始阶段。
   *
   * @param context 当前应用上下文快照（可选）
   *   - hasScene: 是否已加载场景
   *   - hasRegions: 是否已存在 floor/prop 区域
   *
   * 无 context 时从头开始（兼容旧调用）；有 context 时跳过不再适用的阶段。
   */
  function reset(context?: { hasScene: boolean; hasRegions: boolean }) {
    completedPhases.value = new Set()
    activePhaseId.value = null
    currentStepIndex.value = -1
    isWaitingForInteraction.value = false
    showSkipHint.value = false
    // 重置跳过提示标记，让用户重新引导后再次跳过时能看到提示
    localStorage.removeItem(SKIP_HINT_KEY)

    if (context) {
      // 已有场景 → Phase A（打开场景）无需再走
      if (context.hasScene) {
        completedPhases.value.add('open-scene')
      }
      // 已有 region → Phase B（基础认知）中的创建步骤无实操意义，
      // 但视口/面板认知仍有复习价值，故保留 Phase B 不跳过。
      // Phase C（变换操作）在 Phase B 完成后由 SplatStudio.vue 补偿触发。
    }

    saveCompletedPhasesSafe(completedPhases.value)

    // 触发第一个未完成的阶段
    const firstPending = ONBOARDING_PHASES.find((p) => !completedPhases.value.has(p.id))
    if (firstPending) {
      triggerPhase(firstPending.id)
    }
  }

  return {
    completedPhases,
    activePhaseId,
    currentStepIndex,
    isWaitingForInteraction,
    showSkipHint,
    isActive,
    activePhase,
    currentStep,
    totalSteps,
    isLastStep,
    allPhasesCompleted,
    isPhaseCompleted,
    triggerPhase,
    next,
    prev,
    skip,
    dismissSkipHint,
    completePhase,
    markPhaseCompleted,
    resolveInteraction,
    reset,
  }
})
