/**
 * metaParser — meta.json → MetaNodeObject[] 纯函数解析器
 *
 * 识别 5 个已知顶层 key，为每个存在的 key 生成一个只读的 MetaNodeObject。
 * 未识别的顶层 key 不处理（保持简洁）。
 *
 * @changelog
 * | 版本   | 变更说明                                                          | 关联                                                                 |
 * | v1.0.0 | 初始实现：5 个顶层节点解析 + 基于内容的 summary 生成               | REQ: 20260422-splat-studio-meta加载 TECH: 04_design_tech-design.md §3.3.4 |
 * /@changelog
 *
 * @author v_djlzhou
 */

import type { SceneMeta, MetaNodeObject, MetaNodeKey } from '../types/scene'

/** 解析器识别的 5 个顶层 key（顺序即层级树展示顺序） */
const KNOWN_KEYS: readonly MetaNodeKey[] = [
  'gaussianSplatting',
  'collision',
  'terrain',
  'lighting',
  'camera',
]

/** 每个 nodeKey 对应的中文展示名（面板树节点的 name 字段） */
const DISPLAY_NAMES: Record<MetaNodeKey, string> = {
  gaussianSplatting: '高斯泼溅',
  collision: '碰撞',
  terrain: '地形',
  lighting: '光照',
  camera: '相机',
}

/**
 * 将 meta.json 的顶层字段解析为 MetaNodeObject 列表。
 * 输入异常（null / 非对象）时返回空数组，不抛错。
 * 纯函数：不修改入参，无副作用。
 */
export function parseMetaToObjects(meta: SceneMeta | null | undefined): MetaNodeObject[] {
  if (!meta || typeof meta !== 'object') return []

  const result: MetaNodeObject[] = []
  for (const key of KNOWN_KEYS) {
    const raw = meta[key]
    if (raw === undefined || raw === null) continue
    result.push({
      id: `meta-${key}`,
      name: DISPLAY_NAMES[key],
      type: 'meta',
      nodeKey: key,
      summary: makeSummary(key, raw),
      raw,
    })
  }
  return result
}

/**
 * 基于内容生成简短摘要。规则见 tech-design §3.3.4。
 * 全部做防御性访问（?. / typeof 检查），避免因 meta 结构异常抛错。
 */
function makeSummary(key: MetaNodeKey, data: unknown): string {
  if (typeof data !== 'object' || data === null) {
    return String(data ?? '—')
  }
  const d = data as Record<string, unknown>

  switch (key) {
    case 'gaussianSplatting': {
      const models = Array.isArray(d.models) ? d.models : null
      if (models) return models.length > 0 ? `${models.length} 个模型` : '无模型'
      // 兼容其他可能的结构：tiles / splats / items
      const tiles = Array.isArray(d.tiles) ? d.tiles : null
      if (tiles) return `${tiles.length} 个地块`
      return '已定义'
    }
    case 'collision': {
      if (typeof d.enabled === 'boolean') {
        return d.enabled ? '已启用' : '已禁用'
      }
      const colliders = Array.isArray(d.colliders) ? d.colliders : null
      if (colliders) return `${colliders.length} 个碰撞体`
      return '已定义'
    }
    case 'terrain': {
      const tiles = Array.isArray(d.tiles) ? d.tiles : null
      if (tiles) return tiles.length > 0 ? `${tiles.length} 个地块` : '无地块'
      if (typeof d.enabled === 'boolean') {
        return d.enabled ? '已启用' : '已禁用'
      }
      return '已定义'
    }
    case 'lighting': {
      if (typeof d.type === 'string') return d.type
      if (Array.isArray(d.lights)) return `${d.lights.length} 个光源`
      return '默认'
    }
    case 'camera': {
      if (d.position && typeof d.position === 'object') return '已定义初始位置'
      if (typeof d.fov === 'number') return `FOV ${d.fov}°`
      return '默认相机'
    }
    default:
      return '已定义'
  }
}
