<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch } from 'vue'
import './styles/tokens.css'
import MenuBar from './components/layout/MenuBar.vue'
import StatusBar from './components/layout/StatusBar.vue'
import Viewport from './components/viewport/Viewport.vue'
import HierarchyPanel from './components/panels/HierarchyPanel.vue'
import InspectorPanel from './components/panels/InspectorPanel.vue'
import OpenSceneUrlDialog from './components/dialogs/OpenSceneUrlDialog.vue'
import ExportErrorDialog from './components/dialogs/ExportErrorDialog.vue'
import ToastHost from './components/ui/ToastHost.vue'
import ConfirmDialogHost from './components/ui/ConfirmDialogHost.vue'
import { usePanelsStore } from './stores/panels'
import { useSceneStore, LoadSceneError } from './stores/scene'
import { useEditorStore } from './stores/editor'
import { exportSceneConfigAsFile } from './utils/sceneConfigExporter'
import {
  importSceneConfigFromFile,
  ImportSceneConfigError,
  formatImportError,
} from './utils/sceneConfigImporter'
import type { ConfigValidationError } from './utils/sceneConfigValidator'
import { toast } from './composables/useToast'
import { confirm, currentRequest as currentConfirmRequest } from './composables/useConfirm'
import { useTransformShortcuts } from './composables/useTransformShortcuts'
import { useViewShortcuts } from './composables/useViewShortcuts'
import { useEditShortcuts } from './composables/useEditShortcuts'
import { useAutoDraft } from './composables/useAutoDraft'
import { isEditableTarget } from './utils/keyboard'
import { loadDraftStorage, formatSavedAt } from './utils/draftStorage'
import OnboardingOverlay from './components/onboarding/OnboardingOverlay.vue'
import { useOnboardingStore } from './stores/onboarding'
import { useHistoryStore } from './stores/history'

const panelsStore = usePanelsStore()
const sceneStore = useSceneStore()
const editorStore = useEditorStore()
const onboardingStore = useOnboardingStore()
const historyStore = useHistoryStore()

// B07 (REQ 20260506-三模式变换)：挂载全局变换快捷键监听
//   - G/R/T 切模式、X/Y/Z 锁轴、` 切坐标系、Esc 清锁
//   - 与本文件下方既有 handleGlobalKeyDown 共存：Esc 互斥消费（见 useTransformShortcuts 文档）
useTransformShortcuts()

// 正交视角快捷键（Blender 风格小键盘：Numpad 7/1/3 + Ctrl 反向 + Numpad 5 切回透视）
useViewShortcuts()

// v6.0.0: 编辑器快捷键（Ctrl+Z/Y/Shift+Z 撤销重做 + Delete/Backspace 删除）
useEditShortcuts({
  isBlocked: () =>
    showOpenDialog.value ||
    showExportErrorDialog.value ||
    showImportErrorDialog.value ||
    currentConfirmRequest.value !== null,
})

// v7.0.0: 标注草稿自动存档（watch sceneConfig 防抖 800ms → saveDraft）
useAutoDraft()

// 新手引导桥接：分阶段触发
// Phase A (open-scene)：由 OnboardingOverlay 在 mounted 时直接触发
// Phase B (basic-ui)：场景加载成功后触发
// Phase C (transform)：首次创建 floor/prop 后触发
// Phase D (export)：首次导出成功后触发（TODO）

/** 等待上一阶段完成动画后再触发下一阶段的延迟(ms) */
const PHASE_TRANSITION_DELAY = 500
/** 等待 region 渲染稳定后再触发变换引导的延迟(ms) */
const REGION_CREATE_SETTLE_DELAY = 800

watch(
  () => sceneStore.sdkSceneUrl,
  (url, _oldUrl) => {
    // v6.0.0: 场景切换时清空历史栈（无论从哪条路径加载新场景）
    historyStore.clear()

    if (url !== null) {
      // 场景加载成功 → 通知 Phase A 的 interactive 步骤完成
      document.dispatchEvent(new CustomEvent('onboarding:scene-loaded'))
      // 延迟触发 Phase B（等 Phase A 完成动画结束）
      setTimeout(() => {
        document.dispatchEvent(new CustomEvent('onboarding:trigger-basic-ui'))
      }, PHASE_TRANSITION_DELAY)

      // v7.0.0：草稿检测（场景 URL 加载成功后检查是否有未恢复的本地草稿）
      const draft = loadDraftStorage(url)
      if (draft) {
        const timeStr = formatSavedAt(draft.savedAt)
        const floorCount = draft.sceneConfig.floor.length
        const propCount = draft.sceneConfig.prop.length
        toast.info(
          `检测到 ${timeStr} 的未保存草稿（${floorCount} 个地面 / ${propCount} 个对象）`,
          0, // duration=0：不自动消失，等用户主动选择
          [
            {
              label: '恢复',
              onClick() {
                sceneStore.replaceSceneConfig(draft.sceneConfig)
                historyStore.clear()
                toast.success('草稿已恢复')
              },
            },
            {
              label: '放弃',
              onClick() {
                sceneStore.clearDraft()
              },
            },
          ],
        )
      }
    }
  },
)

// 首次创建 floor/prop → 触发 Phase C (变换操作引导)
watch(
  () => sceneStore.sceneConfig.floor.length + sceneStore.sceneConfig.prop.length,
  (count, oldCount) => {
    if (oldCount === 0 && count > 0) {
      setTimeout(() => {
        document.dispatchEvent(new CustomEvent('onboarding:trigger-transform'))
      }, REGION_CREATE_SETTLE_DELAY)
    }
  },
)

// TODO: Phase D (export) — 首次导出成功后触发，待 handleExportConfig 内部接入
//   触发条件：Phase C 已完成 && Phase D 未完成 && 导出成功

// ============================================================
// Phase F (editing-shortcuts / 高效编辑)
//
// 触发条件四合一（全部满足才弹）：
//   1. undoStack.length > 0（用户至少执行过一次可撤销操作）
//   2. Phase C (transform) 已完成（确保先学会变换再学快捷键）
//   3. 无活跃引导 + Phase F 未完成
//   4. 当前有选中对象（确保引导气泡能锚定到层级面板的选中行）
//
// 四个 watch 分别监听 undoStack、Phase C 完成、引导结束、选中状态变化，
// 任一信号变化时调用统一的 maybeTriggerEditingShortcutsGuide 检查 & 触发。
// ============================================================
let editingShortcutsTimer: ReturnType<typeof setTimeout> | null = null

function canTriggerEditingShortcutsGuide(): boolean {
  return (
    historyStore.undoStack.length > 0 &&
    onboardingStore.isPhaseCompleted('transform') &&
    !onboardingStore.isPhaseCompleted('editing-shortcuts') &&
    !onboardingStore.isActive &&
    sceneStore.selectedConfigKey !== null
  )
}

function maybeTriggerEditingShortcutsGuide(): void {
  if (editingShortcutsTimer !== null) return
  if (!canTriggerEditingShortcutsGuide()) return

  editingShortcutsTimer = setTimeout(() => {
    editingShortcutsTimer = null
    // 二次校验：500ms 内用户可能撤销导致 undoStack 为空
    if (canTriggerEditingShortcutsGuide()) {
      document.dispatchEvent(new CustomEvent('onboarding:trigger-editing-shortcuts'))
    }
  }, PHASE_TRANSITION_DELAY)
}

// 信号 1：undoStack 长度变化（用户执行了可撤销操作）
watch(
  () => historyStore.undoStack.length,
  () => maybeTriggerEditingShortcutsGuide(),
)

// 信号 2：Phase C 完成（用户完成了变换操作引导）
watch(
  () => onboardingStore.isPhaseCompleted('transform'),
  (completed) => {
    if (completed) maybeTriggerEditingShortcutsGuide()
  },
)

// 信号 3：引导结束（其他 Phase 关闭后重新检查是否可以触发）
watch(
  () => onboardingStore.isActive,
  (active) => {
    if (!active) maybeTriggerEditingShortcutsGuide()
  },
)

// 信号 4：选中状态变化（确保有选中对象时气泡能锚定到层级面板选中行）
watch(
  () => sceneStore.selectedConfigKey,
  (key) => {
    if (key !== null) maybeTriggerEditingShortcutsGuide()
  },
)

/**
 * v6.3.0：取消选中（从有→无）时，若当前处于变换工具态（move/rotate/scale），
 * 自动回到 'select' 中性态。
 *
 * 设计动机（对齐 Blender/Figma 的"无对象 = 无激活变换"直觉）：
 *   · 创建完成 prop_1 后 setTool('move') 让移动按钮高亮——此时有选中，符合预期
 *   · 用户点空白处取消选中后，若 move 仍持续高亮，工具栏显示"已激活但无对象可操作"，
 *     违反"激活 = 有目标可变换"的语义；自动回 select 让工具栏恢复中性态
 *
 * 不影响：
 *   · region-select / face-pick 不在三变换工具集合，不会被改动（独立的 transient 流程）
 *   · ESC 退出框选已有独立路径 restoreToolBeforeTransient()
 *   · 重新选中对象时 activeTool 仍是 'select'，用户需主动按 G/R/T 进入变换模式（符合
 *     editor store v2.0.0 "默认不激活变换工具" 的设计）
 */
watch(
  () => sceneStore.selectedConfigKey,
  (key, prev) => {
    if (prev !== null && key === null) {
      const cur = editorStore.activeTool
      if (cur === 'move' || cur === 'rotate' || cur === 'scale') {
        editorStore.setTool('select')
      }
    }
  },
)

// 首次切换正交视角 → 触发 Phase E (正交视角引导)
watch(
  () => editorStore.cameraMode,
  (mode) => {
    if (mode !== 'Perspective') {
      document.dispatchEvent(new CustomEvent('onboarding:trigger-ortho-view'))
    }
  },
)

/**
 * 重新引导：根据当前应用状态传入上下文，让 store 智能跳过不适用的阶段。
 * - 已有场景 → 跳过 Phase A（打开场景）
 * - 已有 region → Phase B 完成后自动触发 Phase C（下方 watch 补偿）
 */
function handleRestartOnboarding() {
  const hasScene = sceneStore.sdkSceneUrl !== null
  const hasRegions = sceneStore.sceneConfig.floor.length + sceneStore.sceneConfig.prop.length > 0
  onboardingStore.reset({ hasScene, hasRegions })
}

// 补偿衔接：重新引导时若已有 region，Phase B 完成后手动触发 Phase C
// （正常流程靠 watch count 从 0→1 触发，重新引导时 count 一直 >0 不会再变）
watch(
  () => onboardingStore.isPhaseCompleted('basic-ui'),
  (completed) => {
    if (completed && !onboardingStore.isPhaseCompleted('transform')) {
      const hasRegions =
        sceneStore.sceneConfig.floor.length + sceneStore.sceneConfig.prop.length > 0
      if (hasRegions) {
        setTimeout(() => {
          document.dispatchEvent(new CustomEvent('onboarding:trigger-transform'))
        }, PHASE_TRANSITION_DELAY)
      }
    }
  },
)

const showOpenDialog = ref(false)

// 引导桥接：Dialog 打开时通知 Phase A 第一步完成
watch(showOpenDialog, (visible) => {
  if (visible) {
    document.dispatchEvent(new CustomEvent('onboarding:dialog-opened'))
  }
})

// v2.0.0: 导出错误 Dialog
const showExportErrorDialog = ref(false)

/* ============================================================
 * v3.2.0: 导入场景配置流程的本地状态
 *
 * - fileInputRef：隐藏的 <input type="file">，由"导入场景配置"菜单项触发 click
 * - importErrors / showImportErrorDialog：复用 ExportErrorDialog 展示业务校验错误
 *   （硬错误 PARSE/SCHEMA 不进 Dialog，走 alert 简易提示，因为这两类错通常一句话能讲清且无字段路径列表）
 * ============================================================ */
const fileInputRef = ref<HTMLInputElement | null>(null)
const importErrors = ref<ConfigValidationError[]>([])
const showImportErrorDialog = ref(false)

/* ============================================================
 * v7.0.0：beforeunload 防数据丢失
 *
 * 有未导出草稿（lastDraftSavedAt !== null）时拦截刷新/关闭，
 * 触发浏览器系统级"确认要离开吗？"对话框。
 *
 * 注意：现代浏览器（Chrome 119+）不显示自定义文案，
 * 只展示系统默认对话框，这已足够作为最后一道防线。
 * ============================================================ */
function handleBeforeUnload(e: BeforeUnloadEvent): void {
  if (sceneStore.lastDraftSavedAt !== null) {
    e.preventDefault()
    e.returnValue = '' // Chrome 需要赋值才能触发系统对话框
  }
}

/* ============================================================
 * v3.0.0: Dialog 冲突清理（ADR-003 / CLARIFY-Q2）
 *
 * 打开任何 Dialog 前，若用户有正在进行中的创建意图（pendingCreateKind !== null），
 * 必须先清零该意图并回退工具为 select。理由：
 *   1. 用户注意力已转移，保留意图会在关闭 Dialog 后造成"我刚才在干嘛？"的困惑
 *   2. 避免 Dialog 期间 pendingCreateKind 与 activeTool 状态不同步
 *   3. 符合 EV-002 模式分流三组问题（全局监听/事件分发的清理）
 *
 * 清零由 requestCancelSelection() 内部完成（它会同时清 pendingSelection + pendingCreateKind + 触发 cancel tick）
 * ============================================================ */

function cleanupBeforeDialog() {
  if (sceneStore.pendingCreateKind !== null) {
    sceneStore.requestCancelSelection()
    editorStore.setTool('select')
  }
}

function openSceneUrlDialog() {
  cleanupBeforeDialog()
  showOpenDialog.value = true
}

/* ============================================================
 * 全局快捷键
 * ============================================================
 *
 * v3.0.0: 移除 TOOL_SHORTCUTS（KeyB → region-select）。
 * 创建入口已唯一收敛到 HierarchyPanel 的 4 处"+新增"按钮，
 * 不再通过键盘快捷键激活 region-select 工具。
 *
 * ESC 双档语义保留不变（region-select 工具下才触发）：
 *   · 第一档（有活跃框选: dragging/committed）→ requestCancelSelection()
 *     requestCancelSelection 内部会同时清理 pendingCreateKind（ADR-003）
 *   · 第二档（idle）                           → setTool('select') 回到普通模式
 */

function handleGlobalKeyDown(e: KeyboardEvent) {
  // 输入框 / 可编辑元素内不触发快捷键
  if (isEditableTarget(e.target)) return
  // Ctrl/Meta 组合键不触发（避免与浏览器/编辑器快捷键冲突）
  if (e.ctrlKey || e.metaKey) return

  // --- ESC：仅取消当前框选，保留 region-select 工具 ---
  //     Dialog 打开时让 Dialog 自己消费 ESC（Dialog 组件内部已绑 @keydown）。
  //     本处只处理 viewport 层的 ESC 语义：在 region-select 工具下执行"双档退出"——
  //       · 第一档：有活跃框选（dragging / committed）→ 取消框选，保留工具
  //       · 第二档：无活跃框选（idle）               → 退出 region-select 工具回到 select
  //     该语义对齐 Figma / Photoshop / Blender 的"撤销栈"心智，避免 idle 态按 ESC 静默失败。
  if (e.code === 'Escape') {
    // 若任一 Dialog / Confirm 打开，让它们自己消费，宿主层不抢
    // 注意：showImportErrorDialog 与 currentConfirmRequest 是 v3.x 后期补齐的，
    //       漏一个就会出现"按 Esc 关 Dialog 同时还把 region-select 工具切回 select"的双消费 bug
    if (
      showOpenDialog.value ||
      showExportErrorDialog.value ||
      showImportErrorDialog.value ||
      currentConfirmRequest.value !== null
    ) return

    // REQ 20260508 (B-08)：face-pick 工具下，ESC → cancelFacePicking
    //   生效优先级：face-pick > region-select 双档
    //   通常情况下 FacePicker 自己已在 capture 阶段消费 Esc（更早），但保留宿主侧防御
    //   分支以应对 FacePicker 实例还未挂载（race condition）的极端情况。
    //   分支放在 region-select 之前：face-pick 是 region-select 的派生中间态，需先匹配。
    if (editorStore.activeTool === 'face-pick') {
      e.preventDefault()
      sceneStore.cancelFacePicking()
      return
    }

    // 仅在 region-select 工具下接管 ESC
    if (editorStore.activeTool === 'region-select') {
      e.preventDefault()
      // 双档语义：
      //   第一档（dragging / committed）→ 取消当前框选，保留工具和创建意图
      //   第二档（idle）                → 退出 region-select 工具回到 move
      //   （落 move 而非 select：退框选后手上已有对象，默认进入可变换态）
      //
      //   注意：第一档只取消"本次框选动作"，不清 pendingCreateKind——
      //   用户只是取消了这次拖拽，创建意图（新增地面/对象）仍然有效，
      //   面板 CTA 应保持"框选中…"态，让用户可以立即重新拖。
      //   requestCancelSelection 会清 pendingCreateKind，故此处绕过它，
      //   直接调只负责取消框选的 cancelSelectionOnly。
      const hasActiveSelection =
        sceneStore.pendingSelection !== null || sceneStore.isSelectionDragging
      if (hasActiveSelection) {
        sceneStore.cancelSelectionOnly()
      } else {
        // 第二档：退出工具 + 清创建意图（完全退出框选模式）
        // 恢复进入框选前的工具状态（可能是 'select' / 'move' / 'rotate' 等）
        sceneStore.requestCancelSelection()
        editorStore.restoreToolBeforeTransient()
      }
      return
    }
    return
  }
}

onMounted(() => {
  window.addEventListener('keydown', handleGlobalKeyDown)
  // v7.0.0：有未导出草稿时拦截刷新/关闭，弹系统"确认离开？"对话框
  window.addEventListener('beforeunload', handleBeforeUnload)
})

onBeforeUnmount(() => {
  window.removeEventListener('keydown', handleGlobalKeyDown)
  window.removeEventListener('beforeunload', handleBeforeUnload)
  // 清理 Phase F 延迟 timer
  if (editingShortcutsTimer !== null) {
    clearTimeout(editingShortcutsTimer)
    editingShortcutsTimer = null
  }
})

/**
 * 处理「导出场景配置」菜单事件。
 * 流程（tech-design §3.4.8）:
 *   1. 读取 sceneStore.configValidationErrors
 *   2. 有错误 → 打开 ExportErrorDialog（开 Dialog 前先清创建意图）
 *   3. 无错误 → 调用 exporter 触发下载
 */
function handleExportConfig() {
  if (sceneStore.configValidationErrors.length > 0) {
    cleanupBeforeDialog()
    showExportErrorDialog.value = true
  } else {
    exportSceneConfigAsFile(sceneStore.sceneConfig)
    // 与导入对称：成功反馈含 sceneId 让用户确认下载的是哪一份
    toast.success(`已导出 ${sceneStore.sceneConfig.sceneId}.json`)
    // v7.0.0：有文件了，草稿使命终结
    sceneStore.clearDraft()
  }
}

/**
 * 处理「最近文件 → 选择 URL」菜单事件（v3.1.0）。
 *
 * 与 OpenSceneUrlDialog 内部加载流程对齐：直接 await loadSceneFromUrl，
 * 成功 → store 内部已完成 sdkSceneUrl/recentUrls 原子提交，Viewport watch 自动切换；
 * 失败 → 错误已写入 sceneStore.lastLoadError，把 OpenSceneUrlDialog 打开让用户看到
 *        既有的错误展示流程（避免重复错误 UI 路径）。
 *
 * 注意：开启加载流程前同样要走 cleanupBeforeDialog（保持与 openSceneUrlDialog 一致的清理语义）。
 */
async function handleLoadRecentUrl(url: string) {
  cleanupBeforeDialog()
  try {
    await sceneStore.loadSceneFromUrl(url)
    // v6.0.0: 切换场景后清空历史栈
    historyStore.clear()
  } catch (e) {
    // loadSceneFromUrl 内部抛 LoadSceneError；其他异常包裹一层保持类型一致
    sceneStore.lastLoadError =
      e instanceof LoadSceneError
        ? e
        : new LoadSceneError('NETWORK_ERROR', String((e as Error)?.message ?? e), e)
    showOpenDialog.value = true
  }
}

/* ============================================================
 * v3.2.0: 导入场景配置流程
 *
 * 设计要点：
 *   1. 触发 → 隐藏 file input.click()，浏览器弹原生选择器
 *   2. 选完文件 → onFileChange 走 importSceneConfigFromFile
 *      ├─ 解析硬错误（PARSE/SCHEMA）→ alert（信息单点，路径已嵌入文案）
 *      ├─ 校验业务错误 → ExportErrorDialog 复用展示
 *      └─ 全部通过 → 已有数据时 confirm，确认后 replaceSceneConfig
 *   3. 无论成功失败，把 input.value 清空，让用户能"再选同一个文件"重试
 *
 * 不做的事：
 *   · 不弹自定义"覆盖确认"对话框（使用原生 confirm 即可，避免再加一个 Dialog 组件）
 *   · 不做 undo（PRD 未要求）
 *   · 不在导入成功后切相机视角（导入仅写数据层，不动 ViewerSDK）
 * ============================================================ */

function triggerImportConfig() {
  // 第二道防线（菜单 disabled 是第一道）：防快捷键 / 其他入口绕过菜单约束
  // 给用户明确的引导提示，而不是静默吞掉
  if (sceneStore.sdkSceneUrl === null) {
    toast.warning('请先加载场景（文件 → 打开场景 URL...）')
    return
  }
  cleanupBeforeDialog()
  // 复位 value 让 change 事件即使选同名文件也能触发
  if (fileInputRef.value) fileInputRef.value.value = ''
  fileInputRef.value?.click()
}

/**
 * 判断当前 sceneConfig 是否"非空"——只要 meta 有内容或有任意 floor/prop，
 * 导入覆盖前就 confirm 一次。空白配置则静默替换避免打扰。
 */
function isCurrentConfigDirty(): boolean {
  const c = sceneStore.sceneConfig
  return (
    c.sceneId !== '' ||
    c.name !== '' ||
    c.description !== '' ||
    c.floor.length > 0 ||
    c.prop.length > 0
  )
}

async function onFileChange(e: Event) {
  const input = e.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file) return

  try {
    const { config, validationErrors } = await importSceneConfigFromFile(file)

    if (validationErrors.length > 0) {
      importErrors.value = validationErrors
      showImportErrorDialog.value = true
      return
    }

    // 已有数据时 confirm 二次确认；空白配置静默覆盖
    if (isCurrentConfigDirty()) {
      const ok = await confirm({
        title: '覆盖当前场景配置',
        message: `即将用「${file.name}」覆盖当前场景配置。\n该操作不可撤销。`,
        confirmText: '覆盖',
        kind: 'default',
      })
      if (!ok) return
    }

    sceneStore.replaceSceneConfig(config)
    // v6.0.0: 整体替换后旧命令的 oldState 失效，必须清空历史栈
    historyStore.clear()
    // v7.0.0：导入外部数据覆盖了当前草稿，旧草稿失效
    sceneStore.clearDraft()
    // 成功反馈：含计数让用户立刻确认数据规模
    toast.success(
      `已导入 ${config.floor.length} 个地面 / ${config.prop.length} 个对象`,
    )
  } catch (err) {
    // 硬错误（PARSE/SCHEMA）：路径已嵌入文案（如 "$.prop[2].dimensions.x"），
    // 信息单点，toast 即可承载；error 级 toast 默认 3.5s 给用户读完时间
    if (err instanceof ImportSceneConfigError) {
      toast.error(formatImportError(err), 5000)
    } else {
      toast.error(`导入失败：${(err as Error)?.message ?? String(err)}`, 5000)
    }
  } finally {
    // 复位 input 让用户能重选同一文件
    if (input) input.value = ''
  }
}
</script>

<template>
  <div class="splat-studio-root flex flex-col h-screen w-screen bg-bg-base">
    <!-- Menu Bar (top, fixed) -->
    <MenuBar
      @open-scene-url="openSceneUrlDialog"
      @export-config="handleExportConfig"
      @import-config="triggerImportConfig"
      @load-recent-url="handleLoadRecentUrl"
      @restart-onboarding="handleRestartOnboarding"
    />

    <!-- Main viewport area -->
    <div class="relative flex-1 overflow-hidden">
      <!-- 3D Viewport (full area) -->
      <Viewport />

      <!-- Floating panels (v3.0.0: Toolbar 已下线) -->
      <HierarchyPanel
        v-if="panelsStore.visibility.hierarchy"
        @open-scene-url="openSceneUrlDialog"
        @load-scene-url="handleLoadRecentUrl"
      />
      <InspectorPanel v-if="panelsStore.visibility.inspector" />
    </div>

    <!-- Status Bar (bottom, fixed) -->
    <StatusBar />

    <!-- Dialogs -->
    <OpenSceneUrlDialog v-model:visible="showOpenDialog" />
    <ExportErrorDialog
      v-model:visible="showExportErrorDialog"
      :errors="sceneStore.configValidationErrors"
    />
    <!-- v3.2.0: 导入校验错误（复用 ExportErrorDialog，仅 title 不同） -->
    <ExportErrorDialog
      v-model:visible="showImportErrorDialog"
      :errors="importErrors"
      title="导入校验未通过"
    />

    <!-- v3.2.0: 隐藏的 file input，由"导入场景配置"菜单项触发 click -->
    <input
      ref="fileInputRef"
      type="file"
      accept="application/json,.json"
      class="hidden"
      @change="onFileChange"
    />

    <!-- v3.3.0: 全局 Toast 渲染挂载点（Teleport 到 body，单实例） -->
    <ToastHost />

    <!-- v3.5.0: 全局 Confirm 对话框挂载点（替代 window.confirm，Promise API） -->
    <ConfirmDialogHost />

    <!-- 新手引导蒙层（首次进入自动弹欢迎窗 + Tour） -->
    <OnboardingOverlay />
  </div>
</template>

